"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["43714"],{11017(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.corte_em_area_fora_do_quadro","status":422,"titulo":"A \xe1rea do corte n\xe3o est\xe1 em todos os grupos do quadro de pesos por \xe1rea"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.corte_em_area_fora_do_quadro","requisitos":[],"oQueAconteceu":["Uma elimina\xe7\xe3o por corte em \xe1rea (`ELIMINACAO_CORTE_EM_AREA`) cita, em `areaCodigo`, uma \xe1rea que\\nn\xe3o existe em todos os grupos do quadro de pesos por \xe1rea da classifica\xe7\xe3o. A \xe1rea aceita \xe9 a\\nque todo grupo do quadro tem, e o quadro \xe9 o que a resolu\xe7\xe3o de Pesos por \xc1rea declarada\\ntrouxe do cadastro de Configura\xe7\xe3o. A mensagem do erro lista as \xe1reas aceitas, com c\xf3digo e\\nr\xf3tulo, ou informa que n\xe3o h\xe1 nenhuma quando os grupos n\xe3o t\xeam \xe1rea em comum.","A recusa vem no campo `regrasEliminacao[i].areaCodigo` e acumula, na mesma resposta, com as\\ndemais viola\xe7\xf5es da classifica\xe7\xe3o.","A confer\xeancia s\xf3 roda na classifica\xe7\xe3o com c\xe1lculo local baseada em ENEM, quando o quadro de\\npesos foi congelado. Se a resolu\xe7\xe3o de Pesos por \xc1rea foi recusada na mesma requisi\xe7\xe3o, n\xe3o h\xe1\\nquadro contra o qual conferir, e esta causa s\xf3 aparece depois que a resolu\xe7\xe3o for corrigida.\\nUm corte repetido para a mesma \xe1rea \xe9 recusado s\xf3 por\\n[`corte_em_area_repetido`](/erros/uniplus.selecao.configuracao_classificacao.corte_em_area_repetido).","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na defini\xe7\xe3o da classifica\xe7\xe3o, conforme a causa:","- **O c\xf3digo da \xe1rea est\xe1 errado:** use um dos c\xf3digos listados como aceitos na mensagem do\\n  erro.\\n- **A \xe1rea existe s\xf3 em alguns grupos do quadro:** escolha uma \xe1rea comum a todos os grupos,\\n  ou ajuste o cadastro de Pesos por \xc1rea (Configura\xe7\xe3o) para que todos os grupos da resolu\xe7\xe3o\\n  tenham a \xe1rea, e envie a classifica\xe7\xe3o de novo.\\n- **O processo n\xe3o deve eliminar por corte nessa \xe1rea:** remova a elimina\xe7\xe3o da lista.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);